package org.sleepwell.app;
import android.content.Context;import android.os.SystemClock;import java.util.*;import java.util.concurrent.*;import java.util.function.BooleanSupplier;
/** Secondary GET-only hub snapshots for an explicitly started manual recording. No foreground upgrade. */
final class PirNight implements AutoCloseable {
 private static final ScheduledThreadPoolExecutor WORKER=new ScheduledThreadPoolExecutor(1,r->new Thread(r,"pir-night"));static{WORKER.setRemoveOnCancelPolicy(true);}private final Context app;private final long session,wall=System.currentTimeMillis(),elapsed=SystemClock.elapsedRealtime();private final String token=UUID.randomUUID().toString();private final PirSettings.Frozen settings;private final Records.Factory records;private final BooleanSupplier owner;private volatile boolean closed,paused;private volatile long generation;private volatile PirHttp request;private ScheduledFuture<?> pending;private PirConfig config;private long start;private boolean admitted;
 private PirNight(Context context,long session,BooleanSupplier owner){app=context.getApplicationContext();this.session=session;this.owner=owner;records=Records.factory;PirSettings.Frozen frozen;try{frozen=PirSettings.capture(app);}catch(RuntimeException unreadable){frozen=null;}settings=frozen;}
 static PirNight start(Context context,long session,BooleanSupplier ownedActive){if(session<=0||ownedActive==null)throw new IllegalArgumentException("A real owned recording is required.");PirNight night=new PirNight(context,session,ownedActive);WORKER.execute(night::begin);return night;}
 private void begin(){if(closed)return;try(Store store=records.open(app)){List<org.json.JSONObject> rows=store.rows("SELECT start FROM sessions WHERE id=? AND end IS NULL AND source='tracked'",Long.toString(session));if(rows.size()!=1||!owner.getAsBoolean()&&!paused)return;start=rows.get(0).optLong("start");try{if(settings==null)throw new IllegalStateException("PIR settings unreadable.");config=PirSettings.load(settings);}catch(Exception invalid){PirStore.begin(store,session,"",token,"error","CONFIG",()->!closed&&(paused||owner.getAsBoolean()));return;}PirStore.begin(store,session,config.enabled?config.policy():"",token,config.enabled?(paused?"paused":"active"):"off","",()->!closed&&(paused||owner.getAsBoolean()));admitted=true;if(config.enabled&&!closed&&!paused)schedule(0);}catch(Exception failure){if(!closed&&(paused||owner.getAsBoolean()))Prefs.put(app,"pirError","PIR recording could not be opened. Primary tracking continues.");}}
 private void schedule(long delay){if(!closed&&!paused&&config!=null&&config.enabled)pending=WORKER.schedule(this::poll,delay,TimeUnit.MILLISECONDS);}
 private boolean live(long ticket){return !closed&&!paused&&generation==ticket&&owner.getAsBoolean();}
 private void poll(){long ticket=generation;if(!live(ticket))return;PirHttp.Reading reading;PirHttp http=new PirHttp();request=http;try{reading=http.read(config,()->live(ticket));if(!reading.deviceClass.equals(config.deviceClass))reading=new PirHttp.Reading(null,"UNSUPPORTED",config.deviceClass,reading.age,reading.latency);}catch(Exception failure){reading=new PirHttp.Reading(null,"UNAVAILABLE",config.deviceClass,null,0);}finally{request=null;}if(!live(ticket))return;long nowElapsed=SystemClock.elapsedRealtime(),time=wall+(nowElapsed-elapsed);if(Math.abs(System.currentTimeMillis()-time)>5000)reading=new PirHttp.Reading(null,"CLOCK_CHANGED",config.deviceClass,reading.age,reading.latency);try(Store store=records.open(app)){PirStore.append(store,session,token,time,time-start,reading,()->live(ticket));PirStore.status(store,session,token,"active",reading.quality.equals("UNAVAILABLE")?"CONNECTION":"");}catch(Exception storage){if(live(ticket)){closed=true;try(Store store=records.open(app)){PirStore.status(store,session,token,"error","STORAGE");}catch(Exception ignored){}Prefs.put(app,"pirError","PIR evidence could not be saved. Primary tracking continues.");}return;}schedule(15000);}
 void pause(){if(closed||paused)return;paused=true;generation++;if(pending!=null)pending.cancel(false);PirHttp http=request;if(http!=null)http.cancel();WORKER.execute(()->status("paused",""));}
 void resume(){if(closed||!paused)return;paused=false;generation++;WORKER.execute(()->{if(!closed&&!paused&&admitted&&config!=null&&config.enabled){status("active","");schedule(0);}});}
 private void status(String state,String error){if(!admitted||config==null||!config.enabled)return;try(Store store=records.open(app)){PirStore.status(store,session,token,state,error);}catch(Exception failure){Prefs.put(app,"pirError","PIR status could not be saved. Primary tracking continues.");}}
 public void close(){if(closed)return;closed=true;generation++;if(pending!=null)pending.cancel(false);PirHttp http=request;if(http!=null)http.cancel();WORKER.execute(()->status("complete",""));}
}
